        "category": "Social Empowerment & Apiculture Biology",
        "q": "Describe the division of labor inside a honeybee hive. What are the three types of bees and their respective duties?",
        "ans": "A beehive functions with extraordinary cooperation and strict division of labor:<br>\n1. <strong>The Queen Bee:</strong> There is only one fertile Queen Bee in each hive. Her sole duty is to lay thousands of eggs daily to maintain the colony.<br>\n2. <strong>Worker Bees (Female):</strong> They make up 95% of the hive population. They perform all the arduous work: flying miles across orchards to collect sweet nectar from flowers, fanning nectar into honey, feeding young larvae, building wax honeycombs, and guarding the entrance against intruders.<br>\n3. <strong>Male Bees (Drones):</strong> They are few in number and do not gather food or work inside the hive; their only role is mating with the queen.",
