        "q": "What important details are printed on an Indian Railways train ticket? Mention any four.",
        "ans": "<strong>Key Details on a Train Ticket:</strong><br>\n1. <strong>PNR Number (Passenger Name Record):</strong> A unique 10-digit booking reference code.<br>\n2. <strong>Train Number &amp; Name:</strong> Identifies the specific express train.<br>\n3. <strong>Date of Journey &amp; Departure Time:</strong> Exact day and scheduled boarding time.<br>\n4. <strong>Coach &amp; Berth Number:</strong> (e.g., Coach B1, Berth 24 - Lower).<br>\n5. <strong>Distance &amp; Total Fare:</strong> Distance traveled in kilometres and ticket cost in rupees.",
