        "category": "Comparative Geography & Natural Resources",
        "q": "Why is petrol cheaper than drinking water in Abu Dhabi? What kind of tree is called the 'Date Palm' and why is it the only tree growing in deserts?",
        "ans": "<strong>1. Why Petrol is Cheaper than Water in Abu Dhabi:</strong><br>\nAbu Dhabi is situated on massive subterranean reserves of crude mineral oil (petroleum), which is pumped out easily in billions of barrels. However, because it is an arid desert with zero rivers, lakes, or rainfall, fresh drinking water is extremely scarce and must be produced through expensive seawater desalination plants. Hence, underground petrol is cheaper than purified drinking water.<br><br>\n<strong>2. The Date Palm (Khajoor):</strong><br>\nThe Date Palm is a resilient desert tree uniquely adapted to survive in extreme sand heat with very little water. Its deep roots reach moisture, its waxy fronds prevent water loss, and it yields sweet, energy-rich dates that sustain desert populations.",
