        "category": "Spices of India • Medicinal Uses",
        "q": "Match the following Indian spices with their traditional medicinal benefits:<br>1. Clove (Laung)<br>2. Turmeric (Haldi)<br>3. Fennel (Saunf)<br>4. Black Pepper (Kaali Mirch)",
        "ans": "<strong>Spices and Their Medicinal Benefits:</strong><br>\n1. <strong>Clove (Laung):</strong> Looks like a tiny nail with a crown; clove oil provides instant relief from acute toothache and gum pain.<br>\n2. <strong>Turmeric (Haldi):</strong> Bright yellow antiseptic root; applied on wounds to heal cuts and mixed with warm milk to cure body aches.<br>\n3. <strong>Fennel (Saunf):</strong> Green, sweet, and cooling seeds; chewed after meals to aid digestion and freshen breath.<br>\n4. <strong>Black Pepper (Kaali Mirch):</strong> Small, round, wrinkled black bead; sharp and pungent; cures sore throats and seasonal colds.",
        "marks": 4,
