        "category": "Inclusive Education & Community Action",
        "q": "Why had 9-year-old Chuskit never attended school before? How did Abdul, the teachers, and school children work together to make her dream come true?",
        "ans": "<strong>1. Why Chuskit couldn't attend school:</strong><br>\nChuskit could not use her legs since birth and moved around using a wheelchair. Although her school was not far away across the hill, the pathway was steep, bumpy, and strewn with sharp rocks. Worst of all, there was a fast-flowing glacial stream that had no bridge. A wheelchair could not roll across the rocks or cross the stream, so her grandfather sadly believed school was impossible for her.<br><br>\n<strong>2. How Abdul and the School Solved the Problem:</strong><br>\nAbdul, a compassionate schoolboy, spoke passionately with the Headmaster and teachers, pointing out that Chuskit had every right to study. The Headmaster called a meeting: one group of students and villagers took shovels and leveled the uneven rocky road smooth; another group cut flat wooden planks and constructed a sturdy bridge across the roaring stream. With the path made barrier-free, Chuskit wheeled into the schoolyard to the cheering applause of all teachers and children.",
